/** Refresh the small browser index after data/records.json changes. No packing search is run. */
import { readFileSync, writeFileSync } from "node:fs";
import { planarValues } from "./planar-values";

const file = JSON.parse(readFileSync(new URL("../../../data/records.json", import.meta.url), "utf8"));
const records = file.records;
if (file.units !== "diameter") throw new Error("data/records.json is not in site units (header units: diameter); run scripts/convert-units.ts");
writeFileSync(
  new URL("../src/planar-values.data.ts", import.meta.url),
  "// Generated by packages/surface/scripts/build-planar-values.ts; do not edit by hand.\n" +
    "// A TypeScript module rather than JSON, so that Node imports it without an import attribute.\n" +
    `const planarData = ${JSON.stringify(planarValues(records))};\nexport default planarData;\n`,
);
